CREATE MEMORY TABLE "PUBLIC"."EPISODES"(
    "ADDED_DATE" DATE,
    "AUDIO_QUALITY" INTEGER,
    "BOOKMARKED_QUOTE" BOOLEAN NOT NULL,
    "CONTENT_QUALITY" INTEGER,
    "DURATION_MINUTES" INTEGER,
    "EXPLICIT_CONTENT" BOOLEAN NOT NULL,
    "HOST_CHEMISTRY" INTEGER,
    "LISTENED_DATE" DATE,
    "MINUTES_LISTENED" INTEGER,
    "RATING" INTEGER,
    "RECOMMEND_TO_FRIEND" BOOLEAN NOT NULL,
    "RELEASE_DATE" DATE,
    "REWATCH_VALUE" INTEGER,
    "SEASON_NUMBER" INTEGER,
    "SUBSCRIBED" BOOLEAN NOT NULL,
    "ADDED_BY_ID" BIGINT,
    "CREATED_AT" TIMESTAMP(6),
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 11) NOT NULL,
    "UPDATED_AT" TIMESTAMP(6),
    "EPISODE_NUMBER" CHARACTER VARYING(30),
    "NETWORK" CHARACTER VARYING(50),
    "MAIN_TOPIC" CHARACTER VARYING(100),
    "HOSTS" CHARACTER VARYING(200) NOT NULL,
    "MOOD_TAGS" CHARACTER VARYING(200),
    "SHOW_NAME" CHARACTER VARYING(200) NOT NULL,
    "TITLE" CHARACTER VARYING(250) NOT NULL,
    "GUESTS" CHARACTER VARYING(300),
    "KEY_TAKEAWAY" CHARACTER VARYING(300),
    "MEMORABLE_QUOTE" CHARACTER VARYING(500),
    "PERSONAL_NOTES" CHARACTER VARYING(2000),
    "REVIEW" CHARACTER VARYING(2000),
    "CATEGORY" ENUM('BUSINESS', 'COMEDY', 'EDUCATION', 'HEALTH_WELLNESS', 'HISTORY', 'INTERVIEW', 'MENTAL_HEALTH', 'NEWS_POLITICS', 'POP_CULTURE', 'SCIENCE', 'SOCIETY_CULTURE', 'SPORTS', 'STORYTELLING', 'TECHNOLOGY', 'TRUE_CRIME') NOT NULL,
    "LISTENING_CONTEXT" ENUM('BACKGROUND', 'COMMUTE', 'COOKING', 'FOCUSED_LISTEN', 'HOUSEWORK', 'SLEEP', 'WALKING', 'WORKOUT'),
    "PLAYBACK_SPEED" ENUM('SPEED_0_75X', 'SPEED_1_0X', 'SPEED_1_25X', 'SPEED_1_5X', 'SPEED_1_75X', 'SPEED_2_0X'),
    "STATUS" ENUM('FINISHED', 'LISTENING', 'QUEUED', 'SAVED_FOR_LATER', 'SKIPPED') NOT NULL
);           
